arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" --data "exclude_archived=false&limit=1000&types=public_channel,private_channel" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print(d); sys.exit()
for c in d['channels']:
    n=c.get('name','')
    if 'incident' in n or 'outage' in n or 'checkout' in n:
        print(c['id'], n, '| archived:', c.get('is_archived'), '| topic:', c.get('topic',{}).get('value',''))
"

